  const repactuacaoStatusStyle = (s: RepactuacaoStatus) =>
    s === 'concluido'
      ? { bg: 'rgba(0,174,157,0.20)', border: '1px solid rgba(0,174,157,0.55)' }
      : { bg: 'rgba(245,197,66,0.18)', border: '1px solid rgba(245,197,66,0.55)' }

  const RepactuacaoStatusSelect = (props: {
    value: RepactuacaoStatus
    onChange: (next: RepactuacaoStatus) => void
    disabled?: boolean
  }) => {
    const { value, onChange, disabled } = props
    const [open, setOpen] = useState(false)
    const ref = useRef<HTMLDivElement | null>(null)

    useEffect(() => {
      if (!open) return
      const onDown = (e: MouseEvent) => {
        const el = ref.current
        if (!el) return
        if (e.target instanceof Node && !el.contains(e.target)) setOpen(false)
      }
      const onKey = (e: KeyboardEvent) => {
        if (e.key === 'Escape') setOpen(false)
      }
      window.addEventListener('mousedown', onDown)
      window.addEventListener('keydown', onKey)
      return () => {
        window.removeEventListener('mousedown', onDown)
        window.removeEventListener('keydown', onKey)
      }
    }, [open])

    const base = repactuacaoStatusStyle(value)
    const options: RepactuacaoStatus[] = ['pendente_gerente', 'concluido']

    return (
      <div ref={ref} style={{ position: 'relative' }}>
        <button
          type="button"
          className="control"
          onClick={() => {
            if (disabled) return
            setOpen((v) => !v)
          }}
          disabled={Boolean(disabled)}
          style={{
            width: '100%',
            height: 44,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: 10,
            padding: '10px 12px',
            borderRadius: 12,
            background: base.bg,
            border: base.border,
            color: 'rgba(255,255,255,0.92)',
            cursor: disabled ? 'not-allowed' : 'pointer',
            opacity: disabled ? 0.55 : 1,
          }}
        >
          <span style={{ fontWeight: 850 }}>{repactuacaoStatusLabel(value)}</span>
          <ChevronDown size={18} />
        </button>
        {open ? (
          <div
            style={{
              position: 'absolute',
              top: 'calc(100% + 8px)',
              left: 0,
              right: 0,
              zIndex: 80,
              borderRadius: 12,
              border: '1px solid rgba(255,255,255,0.16)',
              background: 'rgb(12, 22, 40)',
              boxShadow: '0 20px 70px rgba(0,0,0,0.55)',
              overflow: 'hidden',
            }}
          >
            {options.map((opt) => {
              const st = repactuacaoStatusStyle(opt)
              const active = opt === value
              return (
                <button
                  key={opt}
                  type="button"
                  onClick={() => {
                    onChange(opt)
                    setOpen(false)
                  }}
                  style={{
                    width: '100%',
                    textAlign: 'left',
                    padding: '10px 12px',
                    background: active ? st.bg : 'transparent',
                    border: 'none',
                    borderBottom: '1px solid rgba(255,255,255,0.10)',
                    color: 'rgba(255,255,255,0.92)',
                    cursor: 'pointer',
                    fontWeight: active ? 900 : 800,
                  }}
                >
                  {repactuacaoStatusLabel(opt)}
                </button>
              )
            })}
          </div>
        ) : null}
      </div>
    )
  }

